      logs: new Set<LogBoxLog>(),
      isDisabled: false,
      hasError: false,
      selectedLogIndex: -1,
    };

    retry = () => {
      return new Promise<void>((resolve) => {
        this.setState({ hasError: false }, () => {
          resolve();
        });
      });
    };

    render() {
      return (
        <LogContext.Provider
          value={{
            selectedLogIndex: this.state.selectedLogIndex,
            isDisabled: this.state.isDisabled,
            logs: Array.from(this.state.logs),
