        /** @ts-expect-error: react-native types are broken. */
        hovered,
        pressed,
      }) => (
        <View
          style={[dismissStyles.press, hovered && { opacity: 0.8 }, pressed && { opacity: 0.5 }]}>
          <Image
            source={require('@expo/metro-runtime/assets/close.png')}
            style={dismissStyles.image}
          />
        </View>
      )}
    </Pressable>
  );
}

